SELECT t.*, pt.name AS toilet_name, sps.name AS plan_status_name, sa.area_name AS area_name, IFNULL(GROUP_CONCAT(DISTINCT su.user_name), '') AS cleaners_name_str FROM public_toilet_cleaning_task t LEFT JOIN public_toilet pt ON t.toilet_id = pt.toilet_id AND pt.deleted = 0 LEFT JOIN sys_area sa ON pt.area_code = sa.area_code AND sa.deleted = 0 LEFT JOIN sys_plan_status sps ON t.plan_status_id = sps.sys_plan_status_id AND sps.deleted = 0 LEFT JOIN sys_user su ON FIND_IN_SET( su.user_id, REPLACE(REPLACE(REPLACE(REPLACE(t.cleaner_ids, '[', ''), ']', ''), '"', ''), ' ', '') ) AND su.deleted = 0
t.deleted = 0
AND t.toilet_id = #{reqVO.toiletId}
AND t.task_no LIKE CONCAT('%', #{reqVO.taskNo}, '%')
AND t.cleaning_frequency = #{reqVO.cleaningFrequency}
AND t.cleaning_time BETWEEN #{reqVO.cleaningTime[0]} AND #{reqVO.cleaningTime[1]}
AND t.cleaning_content LIKE CONCAT('%', #{reqVO.cleaningContent}, '%')
AND t.cleaning_standard LIKE CONCAT('%', #{reqVO.cleaningStandard}, '%')
AND FIND_IN_SET( #{reqVO.cleanerIds}, REPLACE(REPLACE(REPLACE(REPLACE(t.cleaner_ids, '[', ''), ']', ''), '"', ''), ' ', '') ) > 0
AND t.plan_status_id IN
#{status}
AND t.completion_rate = #{reqVO.completionRate}
AND t.is_abnormal = #{reqVO.isAbnormal}
AND t.abnormal_desc LIKE CONCAT('%', #{reqVO.abnormalDesc}, '%')
AND FIND_IN_SET( #{reqVO.proofUrls}, REPLACE(REPLACE(REPLACE(REPLACE(t.proof_urls, '[', ''), ']', ''), '"', ''), ' ', '') ) > 0
AND t.complete_time BETWEEN #{reqVO.completeTime[0]} AND #{reqVO.completeTime[1]}
AND t.handle_result LIKE CONCAT('%', #{reqVO.handleResult}, '%')
AND t.handle_duration BETWEEN #{reqVO.handleDuration[0]} AND #{reqVO.handleDuration[1]}
AND t.satisfaction LIKE CONCAT('%', #{reqVO.satisfaction}, '%')
AND t.stat_period = #{reqVO.statPeriod}
AND t.review_desc LIKE CONCAT('%', #{reqVO.reviewDesc}, '%')
AND t.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
GROUP BY t.id, pt.toilet_id, pt.name, sa.area_name, sps.sys_plan_status_id, sps.name ORDER BY t.id DESC LIMIT #{reqVO.offset}, #{reqVO.limit}

